examples.code:
#include <atomic>
#include <iostream>

int main() {
    std::atomic<int> counter{0};
    std::atomic_store(&counter, 7);
    std::cout << std::atomic_load(&counter) << "\n";
    std::atomic_store_explicit(&counter, 9, std::memory_order_seq_cst);
    std::cout << std::atomic_load_explicit(&counter, std::memory_order_seq_cst) << "\n";
    std::atomic_init(&counter, 11);
    std::cout << counter.load() << "\n";
}
